        increment(counts, "cart");
        eq(new TreeMap<>(counts), new TreeMap<>(Map.of("home", 2, "cart", 1)));
    });
    test("a write between another thread's read and write is not lost", () -> {
        var counts = new PausingMap<String, Integer>();
        interleave(counts, () -> increment(counts, "home"), () -> increment(counts, "home"));
        eq(counts.get("home"), 2);
    });
    test("the same interleaving on a key that already has a count", () -> {
        var counts = new PausingMap<String, Integer>();
        counts.put("home", 5);
        interleave(counts, () -> increment(counts, "home"), () -> increment(counts, "home"));
        eq(counts.get("home"), 7);
    });
    test("four threads, a thousand increments each", () -> {
        var counts = new ConcurrentHashMap<String, Integer>();
        var pool = Executors.newFixedThreadPool(4);
        var start = new CountDownLatch(1);
        var futures = new ArrayList<Future<?>>();
        for (int t = 0; t < 4; t++) futures.add(pool.submit(() -> { start.await(); for (int i = 0; i < 1000; i++) increment(counts, "home"); return null; }));
