        for (var f : futures) f.get(10, TimeUnit.SECONDS);
        pool.shutdown();
        eq(counts.get("home"), 4000);
    });
    test("a null key is refused (boundary)", () -> {
        raises(NullPointerException.class, () -> increment(new ConcurrentHashMap<>(), null));
    });
    System.exit(report());
