public static void main(String[] args) {
    test("the second lookup reuses the first client", () -> {
        var cache = new ConcurrentHashMap<String, Client>();
        var factory = new CountingFactory();
        var a = clientFor(cache, "acme", factory);
        var b = clientFor(cache, "acme", factory);
        eq(List.of(a == b, factory.built.get()), List.of(true, 1));
    });
    test("a race on one tenant builds one client and both callers share it", () -> {
        var cache = new PausingMap<String, Client>();
        var factory = new CountingFactory();
        var seen = new Client[2];
        interleave(cache, () -> seen[0] = clientFor(cache, "acme", factory), () -> seen[1] = clientFor(cache, "acme", factory));
        eq(List.of(factory.built.get(), seen[0] == seen[1], cache.get("acme") == seen[1]), List.of(1, true, true));
    });
    test("different tenants get different clients", () -> {
        var cache = new ConcurrentHashMap<String, Client>();
        var factory = new CountingFactory();
        eq(List.of(clientFor(cache, "acme", factory).serial(), clientFor(cache, "globex", factory).serial(), cache.size()), List.of(1, 2, 2));
    });
    test("a failing factory caches nothing and the next call tries again (boundary)", () -> {
        var cache = new ConcurrentHashMap<String, Client>();
        var calls = new AtomicInteger();
        Function<String, Client> flaky = t -> { if (calls.incrementAndGet() == 1) throw new IllegalStateException("pool exhausted"); return new Client(t, calls.get()); };
        raises(IllegalStateException.class, () -> clientFor(cache, "acme", flaky), "pool exhausted");
        eq(List.of(cache.containsKey("acme"), clientFor(cache, "acme", flaky).serial()), List.of(false, 2));
    });
    System.exit(report());
}
