public static void main(String[] args) {
    test("tasks that can finish are allowed to finish", () -> {
        var pool = Executors.newSingleThreadExecutor();
        var go = new CountDownLatch(1);
        var ran = new AtomicInteger();
        for (int i = 0; i < 3; i++) pool.execute(() -> { try { go.await(); ran.incrementAndGet(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); } });
        var opener = new Thread(() -> { try { while (!pool.isShutdown()) Thread.sleep(1); } catch (InterruptedException e) { return; } go.countDown(); });
        opener.setDaemon(true);
        opener.start();
        eq(List.of(shutdownGracefully(pool, 2000), ran.get(), pool.isTerminated()), List.of(0, 3, true));
    });
    test("a stuck task is interrupted after the grace period and the queued tasks are counted", () -> {
        var pool = Executors.newSingleThreadExecutor();
        var interrupted = new CountDownLatch(1);
        pool.execute(stuck(interrupted));
        pool.execute(() -> {});
        pool.execute(() -> {});
        int neverStarted = shutdownGracefully(pool, 50);
        eq(List.of(neverStarted, interrupted.await(2, TimeUnit.SECONDS), pool.isTerminated()), List.of(2, true, true));
    });
    test("no new task is accepted once shutdown has begun", () -> {
        var pool = Executors.newSingleThreadExecutor();
        shutdownGracefully(pool, 50);
        raises(RejectedExecutionException.class, () -> pool.execute(() -> {}));
    });
    test("an interrupted caller still shuts the pool down and keeps its interrupt flag (boundary)", () -> {
        var pool = Executors.newSingleThreadExecutor();
        var interrupted = new CountDownLatch(1);
        pool.execute(stuck(interrupted));
        pool.execute(() -> {});
        Thread.currentThread().interrupt();
        int neverStarted = shutdownGracefully(pool, 5000);
        boolean flag = Thread.interrupted();
        eq(List.of(neverStarted, flag, interrupted.await(2, TimeUnit.SECONDS)), List.of(1, true, true));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

