public static void main(String[] args) {
    test("a call runs and returns its result", () -> {
        eq(new Bulkhead(1).call(() -> "ok"), "ok");
    });
    test("with every permit held, the next call is rejected at once without running", () -> {
        var b = new Bulkhead(2);
        var pool = Executors.newFixedThreadPool(3);
        var entered = new CountDownLatch(2);
        var release = new CountDownLatch(1);
        var f1 = hold(pool, b, entered, release);
        var f2 = hold(pool, b, entered, release);
        entered.await(2, TimeUnit.SECONDS);
        var ran = new AtomicBoolean();
        var third = pool.submit(() -> { try { b.call(() -> { ran.set(true); return "x"; }); return "ran"; } catch (Rejected r) { return "rejected"; } });
        String outcome;
        try { outcome = third.get(1, TimeUnit.SECONDS); } catch (TimeoutException e) { outcome = "waited"; }
        int inFlight = b.inFlight();
        release.countDown();
        f1.get(2, TimeUnit.SECONDS);
        f2.get(2, TimeUnit.SECONDS);
        pool.shutdownNow();
        eq(List.of(outcome, ran.get(), inFlight), List.of("rejected", false, 2));
    });
    test("a permit comes back when a call finishes", () -> {
        var b = new Bulkhead(1);
        var pool = Executors.newSingleThreadExecutor();
        var entered = new CountDownLatch(1);
        var release = new CountDownLatch(1);
        var f = hold(pool, b, entered, release);
        entered.await(2, TimeUnit.SECONDS);
        release.countDown();
        f.get(2, TimeUnit.SECONDS);
        pool.shutdown();
        eq(List.of(b.call(() -> "next"), b.inFlight()), List.of("next", 0));
    });
    test("a call that throws gives its permit back and keeps its exception (boundary)", () -> {
        var b = new Bulkhead(1);
        raises(IllegalStateException.class, () -> b.call(() -> { throw new IllegalStateException("recommendations down"); }), "recommendations down");
        eq(List.of(b.inFlight(), b.call(() -> "after")), List.of(0, "after"));
    });
    test("a rejected call holds no permit", () -> {
        var b = new Bulkhead(0);
        raises(Rejected.class, () -> b.call(() -> "never"));
        eq(b.inFlight(), 0);
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

