public static void main(String[] args) {
    test("a fast result is returned", () -> {
        eq(withDeadline(POOL, () -> "9.99", 1000, "cached"), "9.99");
    });
    test("a late task gives the fallback and does not keep running", () -> {
        var probe = new Probe();
        eq(List.of(withDeadline(POOL, blocksForever(probe), 50, "cached"), probe.stoppedOrNeverRan()), List.of("cached", true));
    });
    test("the task's own runtime exception reaches the caller", () -> {
        raises(IllegalArgumentException.class, () -> withDeadline(POOL, () -> { throw new IllegalArgumentException("unknown sku"); }, 1000, "cached"), "unknown sku");
    });
    test("a checked failure is wrapped, with the original as the cause", () -> {
        try {
            withDeadline(POOL, () -> { throw new java.io.IOException("socket closed"); }, 1000, "cached");
            eq("no exception", "IllegalStateException");
        } catch (IllegalStateException e) {
            eq(e.getCause().getMessage(), "socket closed");
        }
    });
    test("an interrupted caller cancels the task and keeps its flag (boundary)", () -> {
        var probe = new Probe();
        var caller = Thread.currentThread();
        var interrupter = new Thread(() -> { try { probe.started.await(2, TimeUnit.SECONDS); } catch (InterruptedException e) { return; } caller.interrupt(); });
        interrupter.setDaemon(true);
        interrupter.start();
        var result = withDeadline(POOL, blocksForever(probe), 5000, "cached");
        boolean flag = Thread.interrupted();
        eq(List.of(result, flag, probe.stopped.await(2, TimeUnit.SECONDS)), List.of("cached", true, true));
    });
    System.exit(report());
}
