        var w = new Worker(s -> {});
        w.queue.addAll(List.of("a", "b"));
        w.progress.await(2, TimeUnit.SECONDS);
        w.thread.interrupt();
        w.thread.join(2000);
        if (w.failure.get() != null) throw w.failure.get();
        eq(w.flagOnExit.get(), true);
    });
